// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(address(this), amount);

        // fund C through its payable fallback
        (bool depOk, ) = address(c).call{value: amount}("");
        require(depOk, "deposit failed");
        require(address(c).balance == amount, "balance not held");

        // owner (this test contract, the deployer) withdraws everything
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
